let renderedDay=today();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&renderedDay!==today()&&location.hash!=='#session')render()});
function render(){renderedDay=today();let [route,id]=location.hash.slice(1).split('/');route=route||'home';if(['chapter','play'].includes(route)){const found=chapters.find(c=>c.id===Number(id));C=found||C;if(route==='play'&&!C.ready)route='chapter';if(route==='play')markStarted()}
if(!['home','chapters','chapter','play','session','dot','space','capstone'].includes(route))route='home';nav(['chapter','play','session'].includes(route)?'chapters':route);({home,chapters:chaptersPage,chapter,play,session:renderSession,dot,space,capstone:()=>window.MU_CAPSTONE?renderCapstone():chaptersPage()}[route])();main.classList.remove('enter');void main.offsetWidth;main.classList.add('enter');window.scrollTo(0,0);main.focus({preventScroll:true})}
